type BeastRow = [string, string, string[], string[], number, number?];
const beast = ([id, name, habitats, attributes, danger, maxAge]: BeastRow): SoulBeastDefinition => {
  const max = maxAge ?? (danger >= 5 ? 100000 : danger === 4 ? 30000 : danger === 3 ? 10000 : danger === 2 ? 3000 : 500);
  return { id, name, habitats, attributes, danger, ageRange: [Math.max(10, Math.floor(max / 100)), max], possibleSkills: [`${attributes[0]}强化`, `${attributes.at(-1)}控制`], description: `${name}是适应${attributes.join("、")}环境的魂兽，实际威胁会随年限和领地状态变化。` };
};

